package d2talalayout

// Recipe `tala-authored-geometry` (tools/fixtures/tala-oracle.toml): the
// D2 object validation TALA's adapter runs before layout
// (validateD2Objects), for one 100x80 object carrying the requested D2
// width/height/top/left attribute bytes. Requests are generated by
// scripts/tala_oracle_fixtures.py authored-geometry-requests.

import (
	"context"
	"encoding/json"
	"os"
	"testing"

	"github.com/d2lang/d2/d2graph"
	"github.com/d2lang/d2/lib/geo"
)

type d2rsAuthoredRequest struct {
	Name     string `json:"Name"`
	ObjectID []int  `json:"ObjectID"`
	Width    *[]int `json:"Width"`
	Height   *[]int `json:"Height"`
	Top      *[]int `json:"Top"`
	Left     *[]int `json:"Left"`
}

func d2rsBytes(values []int) string {
	data := make([]byte, len(values))
	for i, v := range values {
		data[i] = byte(v)
	}
	return string(data)
}

func d2rsScalar(values *[]int) *d2graph.Scalar {
	if values == nil {
		return nil
	}
	return &d2graph.Scalar{Value: d2rsBytes(*values)}
}

func TestD2RSAuthoredGeometry(t *testing.T) {
	out := os.Getenv("D2RS_RECIPE_OUTPUT")
	if out == "" {
		t.Skip("run via scripts/regen-fixtures.py")
	}
	data, err := os.ReadFile(os.Getenv("D2RS_RECIPE_INPUT"))
	if err != nil {
		t.Fatal(err)
	}
	var requests []json.RawMessage
	if err := json.Unmarshal(data, &requests); err != nil {
		t.Fatal(err)
	}
	type row struct {
		Error   string          `json:"error"`
		Request json.RawMessage `json:"request"`
	}
	rows := make([]row, 0, len(requests))
	for _, raw := range requests {
		var request d2rsAuthoredRequest
		if err := json.Unmarshal(raw, &request); err != nil {
			t.Fatal(err)
		}
		g := d2graph.NewGraph()
		id := d2rsBytes(request.ObjectID)
		obj := &d2graph.Object{Graph: g, Parent: g.Root, ID: id, IDVal: id,
			Box: geo.NewBox(nil, 100, 80), Children: make(map[string]*d2graph.Object)}
		obj.WidthAttr = d2rsScalar(request.Width)
		obj.HeightAttr = d2rsScalar(request.Height)
		obj.Top = d2rsScalar(request.Top)
		obj.Left = d2rsScalar(request.Left)
		g.Objects = append(g.Objects, obj)
		g.Root.Children[id] = obj
		g.Root.ChildrenArray = append(g.Root.ChildrenArray, obj)
		message := ""
		if err := validateD2Objects(context.Background(), []d2ObjectVisit{{object: obj, parent: g.Root, depth: 1}}, false); err != nil {
			message = err.Error()
		}
		rows = append(rows, row{Error: message, Request: raw})
	}
	encoded, err := json.MarshalIndent(rows, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(out, append(encoded, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
}
